const {chromium}=require('playwright');const F='file://'+process.argv[2];const S=process.argv[3];
let ok=true;const t=(c,m)=>{if(!c)ok=false;console.log((c?'PASS ':'FAIL ')+m)};
(async()=>{const b=await chromium.launch();const e=[];
const p=await b.newPage({viewport:{width:1440,height:900}});p.on('pageerror',x=>e.push(x.message));
await p.goto(F);await p.evaluate(()=>{localStorage.clear();localStorage.setItem('scopeline-chat-v1',JSON.stringify({features:[],view:'home',mode:'steps'}))});await p.reload();await p.waitForTimeout(300);await p.click('.lp-hero [data-act="new"]');
await p.fill('#start-in','We want one-tap reorder. Support tickets show customers rebuild baskets by hand.');await p.press('#start-in','Enter');
await p.waitForSelector('.m-ai .pcard');await p.click('[data-acceptall]');await p.waitForTimeout(300);
const w0=await p.$eval('.thread-col',x=>x.offsetWidth);
await p.click('.doc-top .min-btn');await p.waitForTimeout(200);
t(await p.locator('.docpane.rail').isVisible(),'definition collapses to a rail');
t(await p.locator('.docpane.rail .segring').count()===1,'rail shows the segmented section ring');
t(await p.locator('.docpane.rail .rail-finish').isVisible(),'rail has a Finish button');
t(await p.locator('.docpane.rail .rgi').count()===6,'rail has one icon button per section group');
const w1=await p.$eval('.thread-col',x=>x.offsetWidth);t(w1>w0+200,'chat gets the freed space ('+w0+'→'+w1+')');
await p.screenshot({path:S+'/collapse-doc.png'});
await p.click('.side-min-btn');await p.waitForTimeout(200);
t(await p.locator('.side.rail').isVisible(),'chats sidebar collapses to a rail');
t(await p.locator('.side.rail .rchat.on .ring').count()===1,'sidebar rail shows each chat as a progress ring');
t(await p.locator('.flowbar .fb-seg').count()===5,'progress bar shows five steps');
t((await p.locator('.fb-next').textContent()).includes('Next'),'progress bar says what to do next');
await p.click('[data-act="howto"]');await p.waitForTimeout(150);t((await p.locator('.howto').textContent()).includes('funnel'),'How it works explains the funnel');
await p.click('.flowbar [data-act="finish"]');await p.waitForTimeout(150);t(await p.locator('.plan2 [data-act="agreeall"]').count()===1,'Finish offers to mark sections agreed');
await p.locator('.plan2 [data-act="agreeall"]').click();await p.waitForTimeout(150);t((await p.locator('.fb-count').textContent()).match(/^[1-9]/)!==null,'agreeing from the finish card updates progress');
const ov=await p.evaluate(()=>{const r=[...document.querySelectorAll('.rail button, .rail .ring, .rail .segring')].map(e=>e.getBoundingClientRect());let n=0;for(let i=0;i<r.length;i++)for(let j=i+1;j<r.length;j++){const a=r[i],b=r[j];if(a.width&&b.width&&a.left<b.right-1&&b.left<a.right-1&&a.top<b.bottom-1&&b.top<a.bottom-1&&!(a.left>=b.left&&a.right<=b.right&&a.top>=b.top&&a.bottom<=b.bottom)&&!(b.left>=a.left&&b.right<=a.right&&b.top>=a.top&&b.bottom<=a.bottom))n++;}return n;});
t(ov===0,'nothing overlaps in the rails ('+ov+')');
const clip=await p.evaluate(()=>[...document.querySelectorAll('.rail *')].filter(e=>e.scrollWidth>e.clientWidth+1&&getComputedStyle(e).overflow!=='visible'&&e.clientWidth>0).length);t(clip===0,'no clipped text in the rails');
await p.screenshot({path:S+'/collapse-both.png'});
await p.reload();await p.waitForTimeout(400);
t(await p.locator('.side.rail').isVisible()&&await p.locator('.docpane.rail').isVisible(),'collapsed state is remembered after reload');
await p.click('.rgi[data-railtab="claims"]');await p.waitForTimeout(200);
t(await p.locator('.docpane:not(.rail) [data-doctab="claims"][aria-selected="true"]').count()===1,'clicking a group in the rail reopens that tab');
await p.click('.side.rail .rail-btn');await p.waitForTimeout(200);
t(await p.locator('.side:not(.rail) .side-list').isVisible(),'sidebar expands again');
// phone: rails never show, tabs still work
const m=await b.newPage({viewport:{width:390,height:844}});m.on('pageerror',x=>e.push(x.message));
await m.goto(F);await m.waitForTimeout(400);
t(!(await m.locator('.docpane.rail').isVisible()),'phone: no rail, full panel via tabs');
const tabs=m.locator('.mobile-tabs button');if(await tabs.count()>1){await tabs.nth(1).click();await m.waitForTimeout(200);t(await m.locator('.doc-full-mobile .docpane').isVisible()||await m.locator('.docpane:not(.rail)').first().isVisible(),'phone: definition tab shows the full panel');}
t(await m.evaluate(()=>document.documentElement.scrollWidth-innerWidth)<=0,'phone: no sideways scroll');
t(e.length===0,'no errors '+e.join('; '));console.log(ok?'ALL PASS':'SOME FAIL');await b.close();})();
